const test = require('node:test');
const assert = require('node:assert/strict');
const { createPluginBundle } = require('../src/plugin-bundle');

test('creates a Figma plugin bundle that imports from its own UI', () => {
  const bundle = createPluginBundle();

  assert.equal(bundle.manifest.ui, 'ui.html');
  assert.equal(bundle.manifest.documentAccess, 'dynamic-page');
  assert.match(bundle.code, /figma\.showUI\(__html__/);
  assert.match(bundle.code, /figma\.setCurrentPageAsync\(page\)/);
  assert.doesNotMatch(bundle.code, /figma\.currentPage\s*=\s*page/);
  assert.match(bundle.code, /type !== 'import'/);
  assert.match(bundle.ui, /parent\.postMessage\(\{ pluginMessage:/);
  assert.match(bundle.ui, /button, \.button\s*\{/);
  assert.match(bundle.ui, /captureSceneGraph/);
  assert.match(bundle.ui, /captureStateGraph/);
  assert.match(bundle.ui, /onState/);
  assert.match(bundle.ui, /import-start/);
  assert.match(bundle.ui, /import-state/);
  assert.match(bundle.ui, /import-finish/);
  assert.match(bundle.ui, /Đang thử.*tương tác/);
  assert.match(bundle.ui, /onProgress/);
  assert.match(bundle.ui, /states\.json/);
  // the file preview must not start a capture; only the button does
  assert.match(bundle.ui, /function show\(file, html\)/);
  assert.doesNotMatch(bundle.ui, /function show\(file, html\)[\s\S]{0,900}await capture(SceneGraph|StateGraph)/);
  assert.match(bundle.ui, /\$\('download'\)\.addEventListener\('click', start\)/);
  assert.match(bundle.ui, /type="checkbox" checked/);
  assert.match(bundle.ui, /\[data-install\]'\)\.style\.display = 'none'/);
  assert.match(bundle.ui, /function pluginCode/);
  assert.match(bundle.ui, /pluginCode\(selected\.scene, selected\.pageName/);
  assert.match(bundle.ui, /id="page-name"/);
  assert.match(bundle.ui, /selected\.pageName/);
  assert.ok(bundle.ui.includes("replace(/\\.[^.]+$/, '')"));
  assert.match(bundle.ui, /name:'scene\.json'/);
  assert.match(bundle.ui, /allow-same-origin/);
  assert.match(bundle.ui, /__bundler_/);
  assert.match(bundle.ui, /base64/);
  assert.match(bundle.ui, /oklch/);
  assert.doesNotMatch(bundle.ui, /<script src="\/(?:scene-capture|plugin-code)\.js"><\/script>/);
  assert.match(bundle.code, /renderScene/);
  assert.match(bundle.code, /message\.scene/);
  assert.match(bundle.code, /uniquePageName/);
  assert.match(bundle.code, /message\.pageName/);
  assert.match(bundle.code, /type:\s*['"]progress/);
  assert.match(bundle.code, /setTimeout/);
  assert.match(bundle.code, /import-start/);
  assert.match(bundle.code, /setReactionsAsync/);
  assert.doesNotMatch(bundle.code, /Generated visual scaffold/);
  assert.doesNotMatch(bundle.code, /Primary action/);
});
